const LESSONS=[
 {id:'caesar',name:'Caesar shift',stage:'Foundations',scope:'Foundation only · not listed for 2027 Div C',time:6,desc:'Learn alphabet shifts as a warm-up for later cipher work.',idea:'Every letter moves by the same number of places. To decrypt, move in the opposite direction; spaces stay where they are.',steps:['Write A–Z and number the letters 0–25.','Try shifting each ciphertext letter left by one, two, then three places.','Read the resulting English sentence and verify every letter.'],cipher:'PHHW DW QRRQ',answer:'MEET AT NOON',hints:['Move P three places back.','P→M and H→E, so the encryption shift was +3.','The full answer is MEET AT NOON.'],why:'Encryption shifts each letter right by 3: M→P and E→H. Shifting the ciphertext left by 3 gives MEET AT NOON.',tool:'caesar'},
 {id:'aristocrat',name:'Aristocrat',stage:'Substitution',scope:'2027 Division C',time:12,desc:'Word spaces remain. Use word shapes, frequency, and a letter mapping.',idea:'Each ciphertext letter consistently stands for one plaintext letter. Spaces remain, so short words and repeated patterns are useful starting points.',steps:['Look for one- to three-letter words and repeated letters.','Guess a short word and record its ciphertext-to-plaintext mapping.','Apply the mapping to the whole sentence; undo guesses that conflict.'],cipher:'CENPGVPR ZNXRF CEBTERFF',answer:'PRACTICE MAKES PROGRESS',hints:['The first word has eight letters: P?A?T?C?.','C→P, E→R, and N→A. Enter these in the mapping grid.','The answer is PRACTICE MAKES PROGRESS.'],why:'This teaching puzzle uses a consistent one-to-one substitution that happens to be ROT13. Competition alphabets are usually less regular; the method is still to build and test a mapping.',tool:'mapping'},
 {id:'patristocrat',name:'Patristocrat',stage:'Substitution',scope:'2027 Division C',time:13,desc:'A substitution cipher with the original word boundaries removed.',idea:'The letter substitution still applies, but spaces no longer reveal word boundaries. Identify common patterns, then separate the recovered letter stream into words.',steps:['Find repeated two- or three-letter patterns.','Try likely fragments such as THE or ING and record a few mappings.','After recovering letters, restore the word breaks.'],cipher:'GURXRLVFCNGVRAPR',answer:'THE KEY IS PATIENCE',hints:['Try THE for the first three letters.','G→T, U→H, R→E. What could XRL be?','The letter stream is THEKEYISPATIENCE.'],why:'Decrypting gives THEKEYISPATIENCE. Adding word breaks makes it THE KEY IS PATIENCE.',tool:'mapping'},
 {id:'xenocrypt',name:'Xenocrypt',stage:'Substitution',scope:'2027 Division C',time:14,desc:'Solve a Spanish substitution using articles, prepositions, and word endings.',idea:'A Xenocrypt commonly hides Spanish plaintext. Do not force English letter frequencies onto it; look for short Spanish words such as LA, EL, DE, and ES.',steps:['Identify possible Spanish short words and endings.','Write down letter mappings; this exercise omits accents.','Check the recovered sentence against Spanish grammar and meaning.'],cipher:'YN PYNIR RF CENPGVPNE',answer:'LA CLAVE ES PRACTICAR',hints:['Try LA for the first word.','YN→LA and RF→ES.','The sentence is LA CLAVE ES PRACTICAR.'],why:'A simple one-to-one substitution hides “The key is to practice.” Real contest vocabulary and alphabets can be more demanding.',tool:'mapping'},
 {id:'baconian',name:'Baconian',stage:'Symbols',scope:'2027 Division C',time:10,desc:'Classify two visual symbols as A or B, then read them in groups of five.',idea:'Five A/B positions represent each plaintext letter. The first job is to distinguish the two symbol classes reliably.',steps:['Label the two visual forms A and B.','Divide the stream into five-symbol groups and consult the Baconian table.','Join the recovered letters and check that they form a word.'],cipher:'AAABA  ABBBA  AAABB  AABAA',answer:'CODE',hints:['The first group, AAABA, is C.','The second group, ABBBA, is O.','The four groups read C O D E.'],why:'This exercise uses a 26-letter teaching table: A=AAAAA, B=AAAAB, C=AAABA. In a contest, the two classes may be hidden in typefaces or other visual differences.',tool:'bacon'},
 {id:'morse',name:'Morse & Fractionated Morse',stage:'Symbols',scope:'2027 Div C: Fractionated Morse',time:16,desc:'Learn dots and dashes, then turn Morse streams into three-symbol groups.',idea:'Fractionated Morse joins Morse code with x separators, divides the stream into triples, and substitutes a letter for each triple. This lesson starts with an alphabetical teaching table.',steps:['Translate each ciphertext letter back to a three-symbol group.','Join the groups and treat x as a letter separator.','Read the remaining dots and dashes with a Morse table.'],cipher:'KHOJU',answer:'CODE',hints:['In this teaching table, K→-.-, the first triplet.','KHOJU → -.-.x---x-..x.x.','Split at x: -.-. / --- / -.. / ., which spells CODE.'],why:'Standard Morse gives C=-.-., O=---, D=-.., and E=. This exercise uses alphabetical triplets (starting ..., ..-, ..x); contest puzzles often use a keyed alphabet and longer messages.',tool:'morse'},
 {id:'porta',name:'Porta cipher',stage:'Polyalphabetic',scope:'2027 Division C',time:14,desc:'Use one of 13 reciprocal alphabets chosen by a keyword letter pair.',idea:'Porta groups keyword letters as A/B, C/D, …, Y/Z. Repeat the keyword over the message and use the matching row for each letter.',steps:['Repeat the keyword above the ciphertext.','Find the paired row for each keyword letter.','Look up each ciphertext letter in that row, then read the result.'],cipher:'NYSE',key:'CODE',answer:'MEET',hints:['Write C, O, D, E above N, Y, S, E.','In the C/D row, N corresponds to M.','The decrypted word is MEET.'],why:'Porta is reciprocal: the same row pairs A–M with N–Z in either direction. NYSE with keyword CODE decrypts to MEET.',tool:'porta'},
 {id:'homophonic',name:'Homophonic substitution',stage:'Advanced substitution',scope:'2027 Division C · new',time:15,desc:'Several ciphertext symbols can represent the same plaintext letter.',idea:'A frequent plaintext letter can have more than one ciphertext symbol, spreading out its frequency. Use cribs, repeated patterns, and symbol distribution.',steps:['Record any mappings supplied by the puzzle.','Look for different symbols that could stand for the same common letter.','Test replacements across the whole message; distinct symbols need not mean distinct letters.'],cipher:'41 07 19 74',answer:'MEET',hints:['41 stands for M.','07 and 19 differ, but both stand for E.','74 stands for T, giving MEET.'],why:'The teaching mapping is 41→M, 07→E, 19→E, 74→T. Real 2027 questions require more cryptanalysis; this one isolates the one-to-many idea.',tool:'homophonic'},
 {id:'nihilist',name:'Nihilist substitution',stage:'Coordinates',scope:'2027 Division C',time:17,desc:'Use a 5×5 Polybius square, then add a repeating keyword coordinate.',idea:'First convert letters to row-column coordinates from 11 to 55. Encryption adds the keyword coordinate; decryption subtracts it.',steps:['Write the 5×5 square, combining I/J.','Convert KEY to 25, 15, 54, 25.','Subtract each keyword number from the ciphertext number and look up the coordinate.'],cipher:'38 49 68 40',key:'KEY',answer:'CODE',hints:['38−25=13, which is C.','49−15=34, which is O.','The last two are 68−54=14 and 40−25=15.'],why:'The teaching square is ABCDE / FGHIK / LMNOP / QRSTU / VWXYZ. Coordinates 13, 34, 14, 15 give C, O, D, E. Contest squares may be keyed.',tool:'polybius'},
 {id:'checkerboard',name:'Checkerboard cipher',stage:'Coordinates',scope:'2027 Division C',time:18,desc:'Read letter-pair coordinates from row and column labels.',idea:'Start with the coordinate idea: the first character chooses a row and the second a column. Contest questions can hide row, column, and square keywords.',steps:['Write row labels C O D E S and column labels T R A I N.','Read each two-letter coordinate at its row-column intersection.','Verify the number of groups and recovered letters.'],cipher:'CA DI CI CN',answer:'CODE',hints:['CA means row C, column A: row 1, column 3.','DI means row D, column I: row 3, column 4.','The four groups read C, O, D, E.'],why:'The teaching square is alphabetical. The 2027 contest version has more demanding keyword and cryptanalysis work; this exercise focuses on coordinate reading.',tool:'checkerboard'},
 {id:'cryptarithm',name:'Cryptarithm',stage:'Synthesis',scope:'2027 Division C · base 10',time:18,desc:'Each letter is a unique digit. Use carries and nonzero leading digits.',idea:'The same letter always means the same digit, different letters use different digits, and a leading digit cannot be zero. Work column by column.',steps:['Use the extra digit in the sum to infer M=1.','Work through each column and its carry.','Check the completed ordinary arithmetic.'],cipher:'SEND + MORE = MONEY',answer:'9567+1085=10652',hints:['Two four-digit numbers make a five-digit sum, so M=1.','In the classic solution, O=0, S=9, E=5.','SEND=9567, MORE=1085, MONEY=10652.'],why:'9567 + 1085 = 10652. The distinct-letter mapping is S9 E5 N6 D7 M1 O0 R8 Y2.',tool:'cryptarithm'},
 {id:'columnar',name:'Complete columnar',stage:'Synthesis',scope:'2027 Division C',time:18,desc:'Write letters into a complete rectangle, then read columns in keyword order.',idea:'The last row is filled so every column has the same length. The letters stay the same; only their positions change.',steps:['ZEBRA has five columns; ten letters make two complete rows.','Read columns in keyword order A, B, E, R, Z.','Split ciphertext into five two-letter groups and restore the original columns.'],cipher:'ANEOENTOMT',key:'ZEBRA',answer:'MEET AT NOON',hints:['Split the text as AN / EO / EN / TO / MT.','These are original columns 5, 3, 2, 4, 1.','Read the rows to get MEETATNOON.'],why:'The original rows are M E E T A / T N O O N. Reading columns in ZEBRA keyword order yields AN EO EN TO MT.',tool:'columnar'}
];
const STAGES=[{name:'Foundations',description:'Build alphabet intuition with a shift cipher before contest types.',ids:['caesar']},{name:'Substitution',description:'Move from word boundaries to unspaced text, Spanish, and one-to-many symbols.',ids:['aristocrat','patristocrat','xenocrypt','homophonic']},{name:'Symbols',description:'Practice two-symbol codes, Morse, and triplets.',ids:['baconian','morse']},{name:'Polyalphabetic & coordinates',description:'Use keyword alphabets and 5×5 squares.',ids:['porta','nihilist','checkerboard']},{name:'Synthesis',description:'Mix logic and transposition under time pressure.',ids:['cryptarithm','columnar']}];
const MAIN=document.getElementById('main');
const STORAGE='codebusters-2027-progress-v1';
let progress=loadProgress();let view='home';let activeLesson='caesar';let hintCount={};let mock=null;let tick=null;
function loadProgress(){try{return JSON.parse(localStorage.getItem(STORAGE))||{done:{},attempts:0,bestMock:0}}catch{return{done:{},attempts:0,bestMock:0}}}
function saveProgress(){try{localStorage.setItem(STORAGE,JSON.stringify(progress))}catch{}}
function norm(x){return String(x||'').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Z0-9]/g,'')}
function findLesson(id){return LESSONS.find(x=>x.id===id)}
function countDone(){return Object.keys(progress.done).filter(x=>progress.done[x]).length}
function button(label,action,cls='secondary'){return `<button class="${cls}" data-action="${action}">${label}</button>`}
function navigate(next,id){view=next;if(id)activeLesson=id;location.hash=next==='lesson'?`lesson/${id}`:next;render();window.scrollTo(0,0);document.getElementById('sidebar').classList.remove('open');document.getElementById('menu-toggle').setAttribute('aria-expanded','false')}
function syncLanguageLinks(){for(const id of ['lang-switch','lang-switch-mobile']){const link=document.getElementById(id);if(link)link.href=`zh.html${location.hash}`}}
function renderNav(){
  document.querySelectorAll('.nav-button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
  document.getElementById('lesson-nav').innerHTML=LESSONS.map(l=>`<button class="lesson-link ${progress.done[l.id]?'done':''} ${view==='lesson'&&activeLesson===l.id?'active':''}" data-lesson="${l.id}"><span class="dot"></span><span>${l.name}</span></button>`).join('');
  document.getElementById('sidebar-progress').textContent=`${countDone()} / ${LESSONS.length} mastered`;
  document.getElementById('sidebar-progress-bar').style.width=`${countDone()/LESSONS.length*100}%`;
}
function render(){renderNav();syncLanguageLinks();MAIN.innerHTML=view==='home'?home():view==='lessons'?courses():view==='lesson'?lesson(findLesson(activeLesson)):view==='mock'?mockPage():resources();if(view==='lesson')activateTool(findLesson(activeLesson));if(view==='mock')renderMockTimer()}
function home(){
  const next=LESSONS.find(l=>!progress.done[l.id])||LESSONS[1];
  return `<div class="page-top"><div><h1>Learn to read every cipher.</h1><p>A guided Codebusters path for high school students. Learn the method, try a short puzzle, and build speed.</p></div><button class="top-action" data-view="resources">Check the event scope ↗</button></div>
  <div class="summary"><div><h2>Up next: ${next.name}</h2><p>${next.desc}</p></div><button class="primary" data-lesson="${next.id}">Continue learning →</button></div>
  <div class="stats"><div class="stat"><strong>${countDone()} / ${LESSONS.length}</strong><span>Lessons mastered</span></div><div class="stat"><strong>${progress.attempts||0}</strong><span>Practice submissions</span></div><div class="stat"><strong>${progress.bestMock||0} / 5</strong><span>Best mock score</span></div></div>
  <div class="notice"><p><strong>2027 scope:</strong> Caesar is a foundation lesson, not a listed 2027 Division C cipher. Ordinary Morse is preparation for Fractionated Morse. These original short puzzles teach the ideas; they are not official test questions. Check the <a href="https://www.soinc.org/rules-2027" target="_blank" rel="noopener">Division C rules manual</a> and any later corrections before competing.</p></div>
  <div class="section-head"><h2>Learning path</h2><p>Follow the stages or jump to a cipher.</p></div><div class="stage-list">${STAGES.map(s=>`<section class="stage"><div><h3>${s.name}</h3><p>${s.description}</p></div><div class="stage-links">${s.ids.map(id=>{const l=findLesson(id);return `<button class="${progress.done[id]?'complete':''}" data-lesson="${id}">${progress.done[id]?'Mastered · ':''}${l.name}</button>`}).join('')}</div></section>`).join('')}</div>`;
}
function courses(){return `<div class="page-top"><div><h1>All lessons</h1><p>Twelve topics arranged by solving skill. The 2027 Division C labels follow the sources on the Resources page.</p></div><button class="top-action" data-view="mock">Try the timed mock</button></div><div class="course-grid">${LESSONS.map(l=>`<article class="course"><div><span class="status ${progress.done[l.id]?'done':l.id==='caesar'?'foundation':'current'}">${progress.done[l.id]?'Mastered':l.scope}</span></div><h3>${l.name}</h3><p>${l.desc}</p><div class="course-footer"><span class="micro">About ${l.time} min · ${l.stage}</span><button class="text-button" data-lesson="${l.id}">Open lesson →</button></div></article>`).join('')}</div>`}
function lesson(l){if(!l)return courses();const idx=LESSONS.indexOf(l),next=LESSONS[idx+1];return `<div class="page-top"><div><h1>${l.name}</h1><p>${l.desc}</p></div><span class="status ${l.id==='caesar'?'foundation':'current'}">${l.scope}</span></div><div class="lesson-layout"><div><section class="panel"><h2>Understand the idea</h2><p>${l.idea}</p><h3>How to solve it</h3><ol class="steps">${l.steps.map(s=>`<li><span>${s}</span></li>`).join('')}</ol></section><section class="panel" id="exercise"><h2>Try a puzzle</h2><p class="mini">Original teaching puzzle · case, spaces, and punctuation do not affect grading</p><div class="cipher-display">${l.cipher}</div>${l.key?`<p><strong>Given keyword:</strong> <code>${l.key}</code></p>`:''}<label class="field-label" for="answer">Your plaintext or numerical equation</label><textarea id="answer" class="answer-field" placeholder="Write your answer here" spellcheck="false"></textarea><div class="control-row">${button('Check answer','check','primary')}${button('Next hint','hint')}${button('Show explanation','reveal','secondary')}</div><div id="hints" class="hint-list" aria-live="polite"></div><div id="feedback" role="status" aria-live="polite"></div></section><div class="control-row"><button class="secondary" data-view="lessons">← All lessons</button>${next?`<button class="secondary" data-lesson="${next.id}">Next: ${next.name} →</button>`:`<button class="primary" data-view="mock">Try the timed mock →</button>`}</div></div><div><section class="panel" id="tool"><div class="tool-title"><h2>Decoding workbench</h2><span class="micro">Experiment freely</span></div>${toolMarkup(l)}</section><section class="panel"><h2>Takeaway</h2><p>${l.why}</p><p class="mini">A correct submission marks this lesson as mastered in this browser.</p></section></div></div>`}
const AZ='ABCDEFGHIJKLMNOPQRSTUVWXYZ';
function toolMarkup(l){
  if(l.tool==='caesar')return `<p>Move the shift control and watch the live decryption.</p><div class="shift-control"><label for="shift">Shift left <strong id="shift-value">3</strong></label><input id="shift" type="range" min="0" max="25" value="3"></div><div class="shift-preview" id="shift-preview"></div>`;
  if(l.tool==='mapping')return `<p>Enter a plaintext letter under each ciphertext letter. The preview updates as you type.</p><div class="mapping">${AZ.split('').map(c=>`<label>${c}<input maxlength="1" aria-label="Plaintext letter for ${c}" data-map="${c}" autocomplete="off"></label>`).join('')}</div><h3>Current preview</h3><div class="map-preview" id="map-preview"></div><button class="text-button" data-action="clear-map">Clear mapping</button>`;
  if(l.tool==='bacon')return `<p>In this 26-letter teaching table, A is 0 and B is 1. Read five symbols at a time.</p><div class="reference-grid">${AZ.split('').map((c,i)=>`<div>${c} ${i.toString(2).padStart(5,'0').replace(/0/g,'A').replace(/1/g,'B')}</div>`).join('')}</div>`;
  if(l.tool==='morse')return `<p>Join the dots, dashes, and x separators. Each ciphertext letter represents a triple.</p><div class="reference-grid">${AZ.split('').map((c,i)=>`<div>${c} ${triplets()[i]}</div>`).join('')}</div><h3>Useful Morse letters</h3><p class="cipher-display" style="font-size:14px">C -.-.　O ---　D -..　E .　T -　A .-</p>`;
  if(l.tool==='porta')return `<p>The keyword selects paired rows. The table shows A–M and their partners for the rows used here. To decrypt, find the ciphertext letter in its row and read the column heading.</p><div style="overflow-x:auto"><table class="small-table porta-table"><tr><th>Key pair</th>${'ABCDEFGHIJKLM'.split('').map(c=>`<th>${c}</th>`).join('')}</tr>${[['C/D',1],['O/P',7],['E/F',2]].map(([name,k])=>`<tr><th>${name}</th>${'ABCDEFGHIJKLM'.split('').map((_,i)=>`<td>${AZ[13+(i+k)%13]}</td>`).join('')}</tr>`).join('')}</table></div>`;
  if(l.tool==='homophonic')return `<p>Different symbols may decode to the same letter.</p><table class="small-table"><tr><th>Symbol</th><th>41</th><th>07</th><th>19</th><th>74</th></tr><tr><th>Known letter</th><td>M</td><td>E</td><td>E</td><td>T</td></tr></table><p class="mini">This introductory puzzle supplies the full mapping; real contest questions do not.</p>`;
  if(l.tool==='polybius'||l.tool==='checkerboard')return `<p>${l.tool==='polybius'?'Teaching square: I/J share a cell. Combine the row and column numbers.':'Teaching square: row labels C O D E S; column labels T R A I N.'}</p><table class="small-table"><tr><th></th>${(l.tool==='polybius'?'12345':'TRAIN').split('').map(x=>`<th>${x}</th>`).join('')}</tr>${['ABCDE','FGHIK','LMNOP','QRSTU','VWXYZ'].map((row,i)=>`<tr><th>${l.tool==='polybius'?i+1:'CODES'[i]}</th>${row.split('').map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</table>`;
  if(l.tool==='cryptarithm')return `<p>Work right to left and track carries. Since two four-digit numbers make a five-digit result, start with M.</p><div class="cipher-display" style="font-size:18px;text-align:right">&nbsp; S E N D<br>+ M O R E<br>─────────<br>M O N E Y</div><p class="mini">Same letter, same digit; different letters, different digits; S and M cannot be zero.</p>`;
  if(l.tool==='columnar')return `<p>The original text fills five columns and two rows. Read columns in keyword order.</p><table class="small-table"><tr>${'ZEBRA'.split('').map(c=>`<th>${c}</th>`).join('')}</tr><tr>${'MEETA'.split('').map(c=>`<td>${c}</td>`).join('')}</tr><tr>${'TNOON'.split('').map(c=>`<td>${c}</td>`).join('')}</tr></table><p class="mini">Read columns in order A → B → E → R → Z.</p>`;
  return '';
}
function triplets(){const out=[];for(const a of '.-x')for(const b of '.-x')for(const c of '.-x')if(a+b+c!=='xxx')out.push(a+b+c);return out}
function activateTool(l){if(l.tool==='caesar'){const range=document.getElementById('shift');const update=()=>{document.getElementById('shift-value').textContent=range.value;document.getElementById('shift-preview').textContent=l.cipher.replace(/[A-Z]/g,c=>AZ[(AZ.indexOf(c)-Number(range.value)+26)%26])};range.addEventListener('input',update);update()}if(l.tool==='mapping'){const update=()=>{let map={};document.querySelectorAll('[data-map]').forEach(el=>{const val=el.value.toUpperCase().replace(/[^A-Z]/g,'').slice(0,1);el.value=val;if(val)map[el.dataset.map]=val});document.getElementById('map-preview').textContent=l.cipher.replace(/[A-Z]/g,c=>map[c]||'·')};document.querySelectorAll('[data-map]').forEach(el=>el.addEventListener('input',update));update()}}
function handleCheck(){const l=findLesson(activeLesson),value=document.getElementById('answer').value,box=document.getElementById('feedback');progress.attempts=(progress.attempts||0)+1;if(norm(value)===norm(l.answer)){progress.done[l.id]=true;box.className='feedback good';box.textContent='Correct! '+l.why}else{box.className='feedback bad';box.textContent=value.trim()?'Not quite. Check the letter order, carries, or the next hint.':'Write an answer before checking.'}saveProgress();renderNav()}
function showHint(){const l=findLesson(activeLesson),n=Math.min((hintCount[l.id]||0)+1,l.hints.length);hintCount[l.id]=n;document.getElementById('hints').innerHTML=l.hints.slice(0,n).map((h,i)=>`<div class="hint"><strong>Hint ${i+1}:</strong> ${h}</div>`).join('')}
function reveal(){const l=findLesson(activeLesson),box=document.getElementById('feedback');box.className='feedback';box.textContent=`Answer: ${l.answer}. ${l.why}`}
const MOCK_IDS=['aristocrat','baconian','porta','nihilist','columnar'];
function ensureMock(){if(!mock)mock={started:false,finished:false,remaining:15*60,answers:{},result:null}}
function mockPage(){ensureMock();if(mock.finished)return mockResults();return `<div class="page-top"><div><h1>Timed mock</h1><p>Five original short puzzles from different cipher families. You have 15 minutes; submit to see your score and explanations.</p></div><span class="status current">2027 Div C types · teaching difficulty</span></div>${!mock.started?`<div class="panel"><h2>Ready when you are</h2><p>This short set practices pacing and switching between ciphers. It does not reproduce the official exam's length, point values, or difficulty.</p><button class="primary" data-action="start-mock">Start 15-minute mock</button></div>`:`<div class="mock-layout"><div>${MOCK_IDS.map((id,i)=>{const l=findLesson(id);return `<section class="panel mock-question"><h3>${i+1}. ${l.name}</h3><p class="mini">${l.idea}${l.key?` · Keyword: ${l.key}`:''}</p><div class="cipher-display">${l.cipher}</div><label class="field-label" for="mock-${id}">Plaintext</label><textarea class="answer-field" id="mock-${id}" data-mock-answer="${id}" spellcheck="false" placeholder="Write your answer">${mock.answers[id]||''}</textarea></section>`}).join('')}</div><aside class="mock-side"><div class="panel"><h2>Time remaining</h2><div class="timer" id="timer">15:00</div><p class="mini">The mock submits automatically when time runs out. Answers stay in this page while you work.</p><button class="primary" data-action="submit-mock">Submit and grade</button></div></aside></div>`}`}
function renderMockTimer(){if(!mock?.started||mock.finished)return;const el=document.getElementById('timer');if(!el)return;const m=Math.floor(mock.remaining/60),s=mock.remaining%60;el.textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;el.classList.toggle('urgent',mock.remaining<=60)}
function startMock(){mock={started:true,finished:false,remaining:15*60,answers:{},result:null};clearInterval(tick);render();tick=setInterval(()=>{if(!mock||mock.finished){clearInterval(tick);return}mock.remaining--;renderMockTimer();if(mock.remaining<=0)finishMock()},1000)}
function finishMock(){if(!mock||mock.finished)return;clearInterval(tick);document.querySelectorAll('[data-mock-answer]').forEach(el=>mock.answers[el.dataset.mockAnswer]=el.value);const score=MOCK_IDS.filter(id=>norm(mock.answers[id])===norm(findLesson(id).answer)).length;mock.result=score;mock.finished=true;progress.bestMock=Math.max(progress.bestMock||0,score);progress.attempts=(progress.attempts||0)+MOCK_IDS.length;saveProgress();render()}
function mockResults(){return `<div class="page-top"><div><h1>Mock complete: ${mock.result} / 5</h1><p>Review each explanation to decide what to practice next.</p></div><button class="top-action" data-action="reset-mock">Try again</button></div><div class="stats"><div class="stat"><strong>${mock.result} / 5</strong><span>Correct this time</span></div><div class="stat"><strong>${progress.bestMock||0} / 5</strong><span>Personal best</span></div><div class="stat"><strong>${Math.floor((15*60-mock.remaining)/60)}m ${String((15*60-mock.remaining)%60).padStart(2,'0')}s</strong><span>Time used</span></div></div>${MOCK_IDS.map((id,i)=>{const l=findLesson(id),ok=norm(mock.answers[id])===norm(l.answer);return `<section class="panel mock-result"><h2>${i+1}. ${l.name} <span class="status ${ok?'done':'foundation'}">${ok?'Correct':'Review'}</span></h2><p>Your answer: ${mock.answers[id]?.trim()||'No answer'}</p><div class="mock-answer"><strong>Answer:</strong> ${l.answer}<br>${l.why}</div><button class="text-button" data-lesson="${id}">Review lesson →</button></section>`}).join('')}`}
function resourceCard(title,description,url,label){return `<article class="resource"><h3>${title}</h3><p>${description}</p><a href="${url}" target="_blank" rel="noopener">${label} ↗</a></article>`}
function teacherResources(){return `<div class="section-head"><h2>Four teacher-recommended resources</h2><p>Choose by purpose: practice first, then study the method.</p></div><div class="resource-list">${resourceCard('Puzzle Baron · online cryptograms','Practice English monoalphabetic substitutions, word shapes, letter frequencies, and mapping. This is useful for Aristocrat skills, but it does not cover every Codebusters cipher.','https://cryptograms.puzzlebaron.com/play.php','Practice a puzzle')}${resourceCard('Toebes · Codebusters tools','Create individual questions or practice tests, and find solving guides, the 2026–27 cipher summary, and videos. Choose Division C and the right tournament level.','https://toebes.com/codebusters/index.html','Open the tool site')}${resourceCard('Scio.ly · 2027 study guide','An English guide with 2027 scope, strategy, and individual cipher chapters. It is a community learning resource; the official manual takes precedence.','https://www.scio.ly/guides/codebusters','Read the guide')}${resourceCard('Toebes · Codebusters Overview PDF','John Toebes’s 120-page guide says it is updated for 2026–27. It also contains historical cipher chapters, so check current-use labels and the official rules.','https://toebes.com/codebusters/Samples/CodeBusters_Overview.pdf','Open the PDF')}</div>`}
function resources(){return `<div class="page-top"><div><h1>Resources & rules</h1><p>Get the 2027 Division C manual from the official source. Videos and tools support your study; they do not replace the rules.</p></div></div><div class="notice"><p>As of November 2, 2026, the official 2027 Division C PDF is provided through a form. This site could not inspect the full manual behind that form. Its cipher labels follow the Toebes 2026–27 summary linked from the official Codebusters page. Recheck the manual, <a href="https://www.soinc.org/events/submit-question-and-rule-clarifications" target="_blank" rel="noopener">official clarifications and corrections</a>, and your state tournament requirements.</p></div>${teacherResources()}<div class="section-head"><h2>How to read the competition scope</h2></div><div class="panel"><div class="two-col"><div><h3>2027 Division C types taught here</h3><p>Aristocrat, Patristocrat, Xenocrypt, Baconian, Fractionated Morse, Porta, Homophonic, Nihilist Substitution, Checkerboard, base-10 Cryptarithm, and Complete Columnar.</p></div><div><h3>Foundations and naming</h3><p>Caesar is a foundation exercise, not a listed 2027 Division C type. Ordinary Morse prepares you for Fractionated Morse. Requirements vary by tournament level, and our short puzzles simplify the contest versions.</p></div></div></div><div class="section-head"><h2>Verified source links</h2></div><div class="resource-list">${resourceCard('Official 2027 Division C rules manual','The Science Olympiad rules page provides the PDF after you complete its Division C form.','https://www.soinc.org/rules-2027','Open the official rules')}${resourceCard('Official Codebusters event page','Science Olympiad states that its event-page resources do not extend the current rules. It also links prior-season videos and practice.','https://www.soinc.org/codebusters-c','Open the event page')}${resourceCard('2026–27 cipher summary','The Toebes summary lists ciphers by division and tournament level, with rule-section references. Use it as an interpretation aid.','https://ncc.toebes.com/codebusters/Rule-Summary-2027.html','Read the cipher summary')}${resourceCard('Codebusters video channel','The @Codebusters-sciol channel is linked from the Toebes tool site and has short demonstrations of its cipher tools.','https://www.youtube.com/@Codebusters-sciol','Open the video channel')}${resourceCard('2026 Codebusters preparation webinar','“Advice & Preparation Ideas,” linked from the official Codebusters page. It is from a prior season; verify its scope against the 2027 manual.','https://www.youtube.com/watch?v=rF8qobfKfdw','Watch the webinar')}${resourceCard('Cryptarithm generation video','A teaching video listed on the official Codebusters event page, focused on generating problems.','https://www.youtube.com/watch?v=rH18JSQiS6Q','Watch the video')}${resourceCard('Toebes test builder tutorial','A tool walkthrough linked from the Toebes site for making extra practice.','https://www.youtube.com/watch?v=miV-4S38tX8','Watch the tutorial')}</div>`}
document.addEventListener('click',e=>{const lesson=e.target.closest('[data-lesson]');if(lesson){navigate('lesson',lesson.dataset.lesson);return}const v=e.target.closest('[data-view]');if(v){navigate(v.dataset.view);return}const a=e.target.closest('[data-action]');if(!a)return;switch(a.dataset.action){case'check':handleCheck();break;case'hint':showHint();break;case'reveal':reveal();break;case'clear-map':document.querySelectorAll('[data-map]').forEach(x=>x.value='');document.getElementById('map-preview').textContent=findLesson(activeLesson).cipher.replace(/[A-Z]/g,'·');break;case'start-mock':startMock();break;case'submit-mock':finishMock();break;case'reset-mock':mock=null;render();break}});
document.addEventListener('input',e=>{if(e.target.matches('[data-mock-answer]')&&mock)mock.answers[e.target.dataset.mockAnswer]=e.target.value});
document.getElementById('menu-toggle').addEventListener('click',()=>{const side=document.getElementById('sidebar');const open=side.classList.toggle('open');document.getElementById('menu-toggle').setAttribute('aria-expanded',String(open))});document.getElementById('mobile-mock').addEventListener('click',()=>navigate('mock'));
function fromHash(){const h=location.hash.replace(/^#/,'');if(h.startsWith('lesson/')){const id=h.split('/')[1];if(findLesson(id)){view='lesson';activeLesson=id}}else if(['home','lessons','mock','resources'].includes(h))view=h;else view='home';render()}
window.addEventListener('hashchange',fromHash);fromHash();
